insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:crystal-palace-football-club:eagle-football-holdings-john-textor:spring-2023-to-summer-2024', null, 'Spring 2023 to summer 2024', 'minority_investment', 'sports', 'football', 'Crystal Palace Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--crystal-palace'), null, 'Eagle Football Holdings (John Textor)', 'corporate', (select id from public.companies where lower(name) = lower('Eagle Football Holdings (John Textor)') limit 1), (select id from public.sports_investors where lower(name) = lower('Eagle Football Holdings (John Textor)') limit 1), null, 45, null, null, null, null, 'Eagle Football increases Crystal Palace stake to about 45%', 'Further investments in spring 2023 and summer 2024 took Textor''s Eagle Football holding from about 40% to about 45%. City AM reported a £30m injection to reach around 45%; the amounts per tranche are not stated by the sources found.', 'John Textor public statements', 'https://www.johntextor.org/premier-league-statement', 'web_research')
