  values ('deal:crystal-palace-football-club:goldman-sachs:december-2025', null, 'December 2025', 'stadium_financing', 'sports', 'football', 'Crystal Palace Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--crystal-palace'), null, 'Goldman Sachs', 'institutional', (select id from public.companies where lower(name) = lower('Goldman Sachs') limit 1), (select id from public.sports_investors where lower(name) = lower('Goldman Sachs') limit 1), null, null, 125000000, 'GBP', null, null, 'Crystal Palace secures £125m Goldman Sachs loan for Selhurst Park Main Stand', 'A £125m loan from Goldman Sachs, tied to the stadium development rather than broadcast income, cleared the way for the Main Stand redevelopment to start in January 2026 with Lendlease as contractor. The project lifts capacity from around 26,000 to more than 34,000; reported cost estimates range from over £150m to £200m.', 'StadiumDB', 'https://stadiumdb.com/news/2025/12/england_multimillion_loan_clears_the_way_for_selhurst_park_project_to_begin_in_january', 'web_research')
